WITH exploded AS (SELECT id, effective_from, currency, EXPLODE(tier_prices) AS element FROM price_tiers) SELECT DATE_TRUNC('YEAR', effective_from) AS year_start, currency, AVG(element) FILTER (WHERE currency = 'USD') AS usd_avg_element, COUNT(CASE WHEN currency = 'USD' THEN 1 END) AS usd_count, ROUND(SUM(element) / NULLIF(COUNT(CASE WHEN currency = 'THB' THEN 1 END), 0), 2) AS element_per_thb, COUNT(*) FILTER (WHERE currency = 'THB') AS thb_rows FROM exploded GROUP BY year_start, currency;
